-- Gerado por scripts/insert_natal_deco.mjs — "Rena com Estrias" (rascunho, família Decoração)
insert into prod_designs (id, nome, descricao, familia, estado, acesso_maker, disponivel_consumidor, capa_familia, usa_modo, tags, preco_creditos, scad_template, generation_schema, parametros_default)
values ('rena', 'Rena com Estrias', 'Rena decorativa de Natal com o corpo às estrias, cabeça redonda, hastes e orelhas. Imprime de pé, sem suportes.', 'Decoração', 'rascunho', 'gratuito', false, false, false,
  array['rena', 'natal', 'decoração', 'estrias'], 1, $tpl$// Rena com Estrias — o modelo está em templates/decoracao/partes/rena.scad (backend)
include </app/templates/decoracao/rena.scad>
$tpl$, '{"engine":"openscad","version":1,"parameters":{"deco":{"order":0,"default":"rena","ui":{"widget":"hidden"}},"altura":{"order":1,"type":"number","min":60,"max":220,"unit":"mm","default":130,"ui":{"label":"Altura (sem as hastes)","widget":"slider","step":1}},"largura":{"order":2,"type":"number","min":30,"max":120,"unit":"mm","default":60,"ui":{"label":"Largura","widget":"slider","step":1}},"estrias":{"order":3,"type":"number","min":8,"max":60,"default":24,"ui":{"label":"Número de estrias","widget":"slider","step":1}},"relevo":{"order":4,"type":"number","min":0,"max":4,"unit":"mm","default":1.5,"ui":{"label":"Fundura das estrias","widget":"slider","step":0.1}},"hastes":{"order":5,"type":"number","min":50,"max":160,"unit":"%","default":100,"ui":{"label":"Tamanho das hastes","widget":"slider","step":5}},"orelhas":{"order":6,"type":"boolean","default":true,"ui":{"label":"Orelhas","widget":"checkbox"}},"info_rena":{"order":99,"default":null,"ui":{"widget":"info","text":"🦌 Imprime de pé, sem suportes. Faz várias em tamanhos e cores diferentes (castanho, bege, verde, vermelho) para uma família de renas. Dica: enchimento baixo (5–10 %)."}}}}'::jsonb, '{}'::jsonb)
on conflict (id) do update set nome = excluded.nome, descricao = excluded.descricao, tags = excluded.tags,
  scad_template = excluded.scad_template, generation_schema = excluded.generation_schema;
